const nm=f=>f.replace(/\.[^.]+$/,'').replace(/[_\-]+/g,' ').replace(/\s+/g,' ').trim().replace(/^./,c=>c.toUpperCase());
function avg(src){return new Promise(r=>{const m=new Image();m.crossOrigin='anonymous';m.onload=()=>{try{const c=document.createElement('canvas');c.width=c.height=8;const x=c.getContext('2d');x.drawImage(m,0,0,8,8);const d=x.getImageData(0,0,8,8).data;let R=0,G=0,B=0,n=0;for(let i=0;i<d.length;i+=4){R+=d[i];G+=d[i+1];B+=d[i+2];n++}r('#'+[R,G,B].map(v=>Math.round(v/n).toString(16).padStart(2,'0')).join(''))}catch(e){r('')}};m.onerror=()=>r('');m.src=src})}
async function pool(a,n,f){let i=0;await Promise.all(Array.from({length:Math.min(n,a.length)},async()=>{while(i<a.length){const j=i++;await f(a[j],j)}}))}
