function parseL(t,def){return t.split('\n').map(x=>x.trim()).filter(Boolean).map(L=>{const o={n:'',s:'',d:'',u:'',x:''},pl=[];L.split(/\t|\||;/).map(x=>x.trim()).forEach(f=>{if(/^https?:\/\//i.test(f))o.u=f;else if(/^#[0-9a-f]{3,8}$/i.test(f))o.x=f;else if(f)pl.push(f)});o.n=pl[0]||'';o.s=pl[1]||def;o.d=pl[2]||'';return o}).filter(o=>o.n&&o.n.toLowerCase()!='nombre')}
