function configuradorView(){const types=[['cocina','Cocina'],['closet','Clóset'],['escritorio','Escritorio']];const models={cocina:[['moderno','Cocina lineal'],['isla','Cocina con isla']],closet:[['abatible','Clóset abatible'],['corredizo','Clóset corredizo']],escritorio:[['sencillo','Escritorio sencillo'],['cajones','Escritorio con cajones']]};return `<section class="configurator-intro"><div class="section-kicker">IMAGINA · PERSONALIZA · COTIZA</div><h1>Visualiza tu próximo mueble.</h1><p>Prueba diferentes acabados y descubre una referencia aproximada de cómo podría verse tu proyecto. La imagen es ilustrativa; el diseño final se ajusta a tus medidas y necesidades.</p></section><section class="configurator-layout"><div class="configurator-controls"><div class="config-step"><small>01 · TIPO DE MUEBLE</small><div class="config-type-list">${types.map(([v,n])=>`<button class="${CONFIG.type===v?'on':''}" data-config-type="${v}">${n}</button>`).join('')}</div></div><div class="config-step"><small>02 · MODELO</small><div class="config-type-list">${models[CONFIG.type].map(([v,n])=>`<button class="${CONFIG.model===v?'on':''}" data-config-model="${v}">${n}</button>`).join('')}</div></div><div class="config-step"><small>03 · COLOR O ACABADO</small><div class="config-color-row"><input type="color" data-config-color value="${CONFIG.color}" aria-label="Elegir color"><span>Selecciona el tono que más te guste.</span></div><div class="config-swatches">${['#b58a62','#d8c5a5','#f0ede6','#6d7164','#373735','#8a493b','#a8b5b2','#755c48'].map(c=>`<button style="--swatch:${c}" data-config-swatch="${c}" aria-label="Elegir color ${c}" class="${CONFIG.color===c?'on':''}"></button>`).join('')}</div></div><a class="b" href="${wa()}" target="_blank" rel="noopener" data-config-quote>Me gusta este estilo, quiero cotizar ↗</a></div><div class="configurator-preview"><div class="config-preview-top"><span>VISTA PREVIA</span><small>MODELO REFERENCIAL</small></div><div id="configDrawing">${configuradorSVG()}</div><div class="config-preview-caption"><b>${types.find(x=>x[0]===CONFIG.type)[1]} · ${models[CONFIG.type].find(x=>x[0]===CONFIG.model)[1]}</b><span>Color seleccionado: ${CONFIG.color.toUpperCase()}</span></div></div></section><section class="configurator-note"><b>¿Te gustaría hacerlo realidad?</b><p>Envíanos una foto de tu espacio o tus medidas y te ayudaremos a desarrollar un diseño personalizado.</p><a class="b o" href="#/contacto">Solicitar asesoría</a></section>`}
